body.script:
const state = { devices: [], pdoEntries: [], points: [], warnings: [], activeTable: 'deviceTable', rawXml: '', importedEsis: [], activeImportId: '', groupBy: { pdoTable: 'PDO Index', pointTable: 'PDO Index' }, treeExpandMode: { pdoTable: 'expandAll', pointTable: 'expandAll' }, treeCustomDefaultCollapsed: { pdoTable: false, pointTable: false }, collapsedGroups: {}, headerNotesExpanded: true };
const $ = (id) => document.getElementById(id);
const COLUMN_SOURCES = { deviceTable: { '#': 'Parser 衍生：依 出現順序編號；不是 ESI 原始欄位', 'Vendor ID': 'ESI: /EtherCATInfo/Vendor/Id', 'Vendor Name': 'ESI: /EtherCATInfo/Vendor/Name', 'Product Code': 'ESI: /EtherCATInfo/Descriptions/Devices/Device/Type/@ProductCode', 'Revision No': 'ESI: /EtherCATInfo/Descriptions/Devices/Device/Type/@RevisionNo', 'Type': 'ESI: /EtherCATInfo/Descriptions/Devices/Device/Type/text()', 'Name': 'ESI: /EtherCATInfo/Descriptions/Devices/Device/Name/text()', 'Group Type': 'ESI: /EtherCATInfo/Descriptions/Devices/Device/GroupType/text()', 'FMMU': 'ESI: /EtherCATInfo/Descriptions/Devices/Device/Fmmu/text()', 'Sync Managers': 'ESI: /EtherCATInfo/Descriptions/Devices/Device/Sm；含 @StartAddress、@ControlByte、@Enable 與文字內容' }, pdoTable: { 'Device #': 'Parser 衍生：對應第幾個 ；不是 ESI 原始欄位', 'Module': 'ESI: Device/Type/text()，若空則取 Device/Name/text()', 'Direction': 'Parser 判斷：RxPdo = Output，TxPdo = Input', 'PDO Type': 'ESI 節點名稱：Device/RxPdo 或 Device/TxPdo', 'PDO Index': 'ESI: Device/RxPdo/Index 或 Device/TxPdo/Index', 'PDO Name': 'ESI: Device/RxPdo/Name 或 Device/TxPdo/Name', 'SM': 'ESI: Device/RxPdo/@Sm 或 Device/TxPdo/@Sm', 'Fixed': 'ESI: Device/RxPdo/@Fixed 或 Device/TxPdo/@Fixed', 'Entry #': 'Parser 衍生：該 PDO 內 出現順序；不是 ESI 原始欄位', 'Object Index': 'ESI: Device/RxPdo/Entry/Index 或 Device/TxPdo/Entry/Index', 'Object SubIndex': 'ESI: Device/RxPdo/Entry/SubIndex 或 Device/TxPdo/Entry/SubIndex', 'SubIndex': 'ESI: Device/RxPdo/Entry/SubIndex 或 Device/TxPdo/Entry/SubIndex', 'BitLen': 'ESI: Device/RxPdo/Entry/BitLen 或 Device/TxPdo/Entry/BitLen', 'DataType': 'ESI: Device/RxPdo/Entry/DataType 或 Device/TxPdo/Entry/DataType；若 Entry/Index=0x0000 則顯示 -', 'Entry Name': 'ESI: Device/RxPdo/Entry/Name 或 Device/TxPdo/Entry/Name；若 Entry/Index=0x0000 則顯示 Padding N bits', 'Entry Type': 'Parser 判斷：Entry/Index=0x0000 視為 Padding；Entry/Name=NULL 視為 Reserved；其他為 Object', 'Entry Usage': 'Parser 綜合 Entry Type 與 Assignment Status 判斷：例如 Active Object、Active Padding、Reserved / NULL、Alternative Object', 'Assignment Status': 'Parser 判斷 PDO 啟用狀態；優先依 Device/RxPdo 或 Device/TxPdo 的 @Sm 判斷 Active by SM，若沒有 @Sm 才 fallback 到 Object 0x1C12/0x1C13 default assignment', 'Local Start Bit': 'Parser 衍生：在同一個 PDO Index 內，依該 PDO 的 Entry 順序與 BitLen 從 0 開始累加；不是跨 alternative PDO 的 process image 位置' }, pointTable: { 'Device #': 'Parser 衍生：對應第幾個 ；不是 ESI 原始欄位', 'Module': 'ESI: Device/Type/text()，若空則取 Device/Name/text()', 'Point': '優先 ESI VendorSpecific/PdoDivisions/Division/Name 解析；若無則由 Parser 依 DO/DI 順序產生', 'Raw Name': '若有：ESI VendorSpecific/*/PdoDivisions/Division/Name；若無：Parser 產生 object.bitN', 'Direction': '優先由對應 PDO Type 判斷：RxPdo = Output，TxPdo = Input；找不到時由 Object Index 範圍推論', 'PDO Type': 'ESI 節點名稱：Device/RxPdo 或 Device/TxPdo；由對應 Object Index/SubIndex 回查', 'PDO Index': 'ESI: Device/RxPdo/Index 或 Device/TxPdo/Index；由對應 Object Index/SubIndex 回查', 'Object Index': 'ESI: Entry/Index；或 VendorSpecific/*/PdoDivisions/@Index', 'Object SubIndex': 'ESI: Entry/SubIndex；或 VendorSpecific/*/PdoDivisions/@SubIndex', 'SubIndex': 'ESI: Entry/SubIndex；或 VendorSpecific/*/PdoDivisions/@SubIndex', 'Object Bit Length': 'ESI: Entry/BitLen；若 VendorSpecific 找不到對應 Entry，則依 Division 數量估算', 'Assignment Status': '由對應 PDO Entry 的 Assignment Status 帶入，用來區分 Active by SM / Default Active / Alternative mapping', 'Entry Usage': 'Parser 判斷此 DIO 點位是否為有效 Object；NULL/Reserved entry 不會出現在 DIO 點位表', 'Local Start Bit': 'Parser 衍生：此 DIO 點位在所屬 PDO Index 內的起始 bit；由對應 PDO Entry Local Start Bit + Bit Offset 計算；不是跨 alternative PDO 的 process image 位置', 'Bit Offset': '有 PdoDivisions 時：依 Division 出現順序推得；無 PdoDivisions 時：Parser 依 LSB-first 推論；不是標準 PDO Entry 原始欄位', } };
const FIELD_DICTIONARY = [ // Device table { table: 'Device', title: '#', sourceType: 'Parser 衍生', esiPath: '無；不是 ESI 原始欄位', logic: '依 /EtherCATInfo/Descriptions/Devices/Device 出現順序，由 Parser 從 1 開始編號。', doubleCheck: '在 ESI 搜尋 ，第 1 個 Device 對應 #=1，第 2 個對應 #=2。' }, { table: 'Device', title: 'Vendor ID', sourceType: 'ESI 直接讀取', esiPath: '/EtherCATInfo/Vendor/Id', logic: '讀取 Vendor/Id，例如 #x000116C7，Parser 顯示成 0x000116C7。', doubleCheck: '在 ESI 搜尋 。' }, { table: 'Device', title: 'Vendor Name', sourceType: 'ESI 直接讀取', esiPath: '/EtherCATInfo/Vendor/Name', logic: '讀取 Vendor/Name 文字內容。', doubleCheck: '在 ESI 搜尋 。' }, { table: 'Device', title: 'Product Code', sourceType: 'ESI 直接讀取', esiPath: '/EtherCATInfo/Descriptions/Devices/Device/Type/@ProductCode', logic: '讀取 Device/Type 的 ProductCode attribute，例如 #x1401EB13。', doubleCheck: '在 Device 底下找到 。' }, { table: 'Device', title: 'Revision No', sourceType: 'ESI 直接讀取', esiPath: '/EtherCATInfo/Descriptions/Devices/Device/Type/@RevisionNo', logic: '讀取 Device/Type 的 RevisionNo attribute。', doubleCheck: '在 Device 底下找到 。' }, { table: 'Device', title: 'Type', sourceType: 'ESI 直接讀取', esiPath: '/EtherCATInfo/Descriptions/Devices/Device/Type/text()', logic: '讀取 Device/Type 的文字內容，例如 HCNXE-MD1616-D。', doubleCheck: '在 ESI 搜尋 ...。' }, { table: 'Device', title: 'Name', sourceType: 'ESI 直接讀取', esiPath: '/EtherCATInfo/Descriptions/Devices/Device/Name/text()', logic: '讀取 Device/Name 的文字內容，通常是完整產品描述。', doubleCheck: '在 Device 底下搜尋 。' }, { table: 'Device', title: 'Group Type', sourceType: 'ESI 直接讀取', esiPath: '/EtherCATInfo/Descriptions/Devices/Device/GroupType/text()', logic: '讀取 GroupType 文字內容。', doubleCheck: '在 Device 底下搜尋 。' }, { table: 'Device', title: 'FMMU', sourceType: 'ESI 直接讀取', esiPath: '/EtherCATInfo/Descriptions/Devices/Device/Fmmu/text()', logic: '收集所有 Device/Fmmu 的文字內容，例如 Outputs、Inputs。', doubleCheck: '在 Device 底下搜尋所有 。' }, { table: 'Device', title: 'Sync Managers', sourceType: 'ESI 直接讀取 + 格式化', esiPath: '/EtherCATInfo/Descriptions/Devices/Device/Sm/text() 與 @StartAddress/@ControlByte/@Enable', logic: '收集所有 Sm，顯示 SM 編號、用途文字、StartAddress、ControlByte、Enable。SM 編號由出現順序推得。', doubleCheck: '在 Device 底下搜尋所有 Outputs 或 Inputs。' },
// PDO Entry table { table: 'PDO Entry', title: 'Device #', sourceType: 'Parser 衍生', esiPath: '無；不是 ESI 原始欄位', logic: '對應 Device 表的 #，用來知道此 PDO Entry 屬於第幾個 Device。', doubleCheck: '看該 RxPdo/TxPdo 位於第幾個 底下。' }, { table: 'PDO Entry', title: 'Module', sourceType: 'ESI 直接讀取 + fallback', esiPath: '優先 Device/Type/text()；若空則 Device/Name/text()', logic: 'Parser 用 Device/Type 當模組名稱；若 Type 文字為空，改用 Device/Name。', doubleCheck: '在該 Device 底下檢查 與 。' }, { table: 'PDO Entry', title: 'Direction', sourceType: 'Parser 判斷', esiPath: 'Device/RxPdo 或 Device/TxPdo 的節點名稱', logic: 'RxPdo 判斷為 Output，表示 Master → Slave；TxPdo 判斷為 Input，表示 Slave → Master。', doubleCheck: '看這筆 Entry 是包在 還是 裡。' }, { table: 'PDO Entry', title: 'PDO Type', sourceType: 'ESI 節點名稱', esiPath: 'Device/RxPdo 或 Device/TxPdo', logic: '直接取外層 PDO 節點名稱。', doubleCheck: '看 XML 外層是 或 。' }, { table: 'PDO Entry', title: 'PDO Index', sourceType: 'ESI 直接讀取', esiPath: 'Device/RxPdo/Index 或 Device/TxPdo/Index', logic: '讀取 PDO mapping object 的 Index，例如 0x1600 或 0x1A00。注意這不是實際 DIO object index。', doubleCheck: '在 RxPdo/TxPdo 直屬子節點搜尋 。' }, { table: 'PDO Entry', title: 'PDO Name', sourceType: 'ESI 直接讀取', esiPath: 'Device/RxPdo/Name 或 Device/TxPdo/Name', logic: '讀取 PDO mapping object 的名稱，例如 Output 1、Input 1。', doubleCheck: '在 RxPdo/TxPdo 直屬子節點搜尋 。' }, { table: 'PDO Entry', title: 'SM', sourceType: 'ESI 直接讀取', esiPath: 'Device/RxPdo/@Sm 或 Device/TxPdo/@Sm', logic: '讀取 RxPdo/TxPdo 的 Sm attribute。', doubleCheck: '看 或 。' }, { table: 'PDO Entry', title: 'Fixed', sourceType: 'ESI 直接讀取', esiPath: 'Device/RxPdo/@Fixed 或 Device/TxPdo/@Fixed', logic: '讀取 RxPdo/TxPdo 的 Fixed attribute。', doubleCheck: '看 或 。' }, { table: 'PDO Entry', title: 'Entry #', sourceType: 'Parser 衍生', esiPath: '無；不是 ESI 原始欄位', logic: '同一個 RxPdo/TxPdo 內，第幾個 ，由出現順序從 1 開始編號。', doubleCheck: '數該 RxPdo/TxPdo 底下 Entry 的出現順序。' }, { table: 'PDO Entry', title: 'Object Index', sourceType: 'ESI 直接讀取', esiPath: 'Device/RxPdo/Entry/Index 或 Device/TxPdo/Entry/Index', logic: '讀取真正被 PDO 映射的 Object Dictionary Index，例如 0x7000、0x6000。', doubleCheck: '在 底下搜尋 ，不要跟 PDO Index 混淆。' }, { table: 'PDO Entry', title: 'Object SubIndex', sourceType: 'ESI 直接讀取', esiPath: 'Device/RxPdo/Entry/SubIndex 或 Device/TxPdo/Entry/SubIndex', logic: '讀取真正被 PDO 映射的 Object SubIndex，例如 1 或 2，Parser 顯示成 0x01、0x02。', doubleCheck: '在 底下搜尋 。' }, { table: 'PDO Entry', title: 'BitLen', sourceType: 'ESI 直接讀取', esiPath: 'Device/RxPdo/Entry/BitLen 或 Device/TxPdo/Entry/BitLen', logic: '讀取此 Entry 佔幾個 bit，例如 8。', doubleCheck: '在 底下搜尋 。' }, { table: 'PDO Entry', title: 'DataType', sourceType: 'ESI 直接讀取', esiPath: 'Device/RxPdo/Entry/DataType 或 Device/TxPdo/Entry/DataType', logic: '讀取資料型態，例如 BYTE。若 Entry/Index=0x0000，Parser 會顯示 -，表示這是 padding 而不是有效 Object。', doubleCheck: '在 底下搜尋 ；若 Index 是 #x0 且沒有 DataType，代表 padding。' }, { table: 'PDO Entry', title: 'Entry Name', sourceType: 'ESI 直接讀取或 Parser 標示', esiPath: 'Device/RxPdo/Entry/Name 或 Device/TxPdo/Entry/Name；padding 則由 Parser 產生', logic: '正常 Object 讀取 Entry/Name；若 Entry/Index=0x0000，Parser 顯示 Padding N bits，避免被誤判為漏資料。', doubleCheck: '在 底下搜尋 ；若 Index 是 #x0 且沒有 Name，代表 padding。' }, { table: 'PDO Entry', title: 'Entry Type', sourceType: 'Parser 判斷', esiPath: 'Device/RxPdo/Entry/Index 與 Device/RxPdo/Entry/Name；或 Device/TxPdo/Entry/Index 與 Device/TxPdo/Entry/Name', logic: 'Entry/Index=0x0000 時標示為 Padding；Entry/Name=NULL 時標示為 Reserved；其他有效 Object Index 標示為 Object。Padding 與 Reserved 會保留在 PDO Entry 表，但不會展開成有效 DIO 點位。', doubleCheck: '檢查該 Entry 的 是否為 #x0 / 0x0000，或 是否為 NULL。' }, { table: 'PDO Entry', title: 'Entry Usage', sourceType: 'Parser 判斷', esiPath: '由 Entry Type 與 Assignment Status 組合判斷', logic: '正常 active object 顯示 Active Object；active PDO 內的 padding 顯示 Active Padding；Name=NULL 的 entry 顯示 Reserved / NULL。', doubleCheck: '同時查看 Entry Type 與 Assignment Status。' }, { table: 'PDO Entry', title: 'Assignment Status', sourceType: 'Parser 判斷', esiPath: '優先：Device/RxPdo/@Sm 或 Device/TxPdo/@Sm；Fallback：Dictionary/Objects/Object[Index=0x1C12 或 0x1C13]/Info/SubItem/Info/DefaultData', logic: '若某個 RxPDO/TxPDO 節點直接帶 @Sm，Parser 會優先把該 PDO 視為 Active by SM，其他同方向 PDO 標示 Alternative。若同方向完全沒有 PDO 帶 @Sm，才 fallback 解析 0x1C12/0x1C13 的 DefaultData，命中的 PDO 標示 Default Active。', doubleCheck: '先看 Device 底下的 或 ；若沒有，再看 0x1C12/0x1C13 assignment。這可避免把 alternative PDO 誤判為 active。' }, { table: 'PDO Entry', title: 'Local Start Bit', sourceType: 'Parser 衍生', esiPath: '無；不是 ESI 原始欄位', logic: '在同一個 PDO Index 內，依 Entry 出現順序累加前面 Entry 的 BitLen，得到該 Entry 在該 PDO 內的起始 bit。Alternative PDO 之間不互相累加。', doubleCheck: '只看同一 PDO Index 底下前面 Entry 的 BitLen 加總，不要跨到其他互斥 PDO。' },
// DIO point table { table: 'DIO 點位', title: 'Device #', sourceType: 'Parser 衍生', esiPath: '無；不是 ESI 原始欄位', logic: '對應 Device 表的 #，用來知道此點位屬於第幾個 Device。', doubleCheck: '看該點位來源的 RxPdo/TxPdo 或 PdoDivisions 位於第幾個 底下。' }, { table: 'DIO 點位', title: 'Module', sourceType: 'ESI 直接讀取 + fallback', esiPath: '優先 Device/Type/text()；若空則 Device/Name/text()', logic: '同 PDO Entry 表的 Module。', doubleCheck: '在該 Device 底下檢查 與 。' }, { table: 'DIO 點位', title: 'Point', sourceType: 'ESI 額外描述或 Parser 產生', esiPath: '優先 VendorSpecific/*/PdoDivisions/Division/Name；若無則 Parser 依 DO/DI 順序產生', logic: '若 Raw Name 類似 Output Bit03，Parser 轉成 DO3；若 Raw Name 類似 IN 0A / OUT 0B，Parser 以十六進位點號轉成 DI10 / DO11；若 PDO Entry 本身是 BOOL+BitLen=1，直接視為一個 DIO 點位；若無 PdoDivisions，Parser 依 direction 與累計 bit 編成 DO0/DI0。', doubleCheck: '先找 PdoDivisions/Division/Name；若找不到，查看 Source 是否為 INFERRED_FROM_BYTE_ORDER。' }, { table: 'DIO 點位', title: 'Raw Name', sourceType: 'ESI 額外描述或 Parser 產生', esiPath: '若有：VendorSpecific/*/PdoDivisions/Division/Name；若無：Parser 產生 object.bitN', logic: '保留 ESI 裡 Division/Name 的原始文字；若沒有 PdoDivisions，顯示 0x7000:0x01.bit0 這類 Parser 產生名稱。', doubleCheck: '在 ESI 搜尋 底下的 。' }, { table: 'DIO 點位', title: 'Direction', sourceType: 'Parser 判斷', esiPath: '優先由對應 Object 所在 RxPdo/TxPdo 判斷；找不到對應 PDO Entry 時由 Object Index 範圍推論', logic: '對應 RxPdo 則 Output；對應 TxPdo 則 Input。若只有 PdoDivisions 找不到 PDO Entry，0x7000~0x7FFF 推論 Output，0x6000~0x6FFF 推論 Input。', doubleCheck: '確認 Object Index/SubIndex 是否存在於 RxPdo/Entry 或 TxPdo/Entry；若不存在，看 Warnings。' }, { table: 'DIO 點位', title: 'PDO Type', sourceType: '由 PDO Entry 回查', esiPath: 'Device/RxPdo 或 Device/TxPdo；以 Object Index + SubIndex 對應回查', logic: 'Parser 用 Object Index/SubIndex 找到對應的 PDO Entry，再取它的 PDO Type。', doubleCheck: '拿本列 Object Index/SubIndex 去 PDO Entry 表找同一筆。' }, { table: 'DIO 點位', title: 'PDO Index', sourceType: '由 PDO Entry 回查', esiPath: 'Device/RxPdo/Index 或 Device/TxPdo/Index；以 Object Index + SubIndex 對應回查', logic: 'Parser 用 Object Index/SubIndex 找到對應的 PDO Entry，再取該 PDO 的 Index。', doubleCheck: '拿本列 Object Index/SubIndex 去 PDO Entry 表找對應的 PDO Index。' }, { table: 'DIO 點位', title: 'Object Index', sourceType: 'ESI 直接讀取', esiPath: '優先 PDO Entry 的 Entry/Index；PdoDivisions 來源則讀 PdoDivisions/@Index', logic: '若點位來自 PdoDivisions，讀取 PdoDivisions 的 Index attribute；若點位由 PDO Entry 推論，讀取 Entry/Index。', doubleCheck: '看 Source；ESI_VENDOR_SPECIFIC 時查 PdoDivisions/@Index，INFERRED 時查 PDO Entry/Index。' }, { table: 'DIO 點位', title: 'Object SubIndex', sourceType: 'ESI 直接讀取', esiPath: '優先 PDO Entry 的 Entry/SubIndex；PdoDivisions 來源則讀 PdoDivisions/@SubIndex', logic: '若點位來自 PdoDivisions，讀取 PdoDivisions 的 SubIndex attribute；若點位由 PDO Entry 推論，讀取 Entry/SubIndex。', doubleCheck: '看 Source；ESI_VENDOR_SPECIFIC 時查 PdoDivisions/@SubIndex，INFERRED 時查 PDO Entry/SubIndex。' }, { table: 'DIO 點位', title: 'Object Bit Length', sourceType: 'ESI 直接讀取或估算', esiPath: '優先對應 PDO Entry/BitLen；若 PdoDivisions 找不到對應 Entry，則用 Division 數量估算', logic: '正常情況會回查 PDO Entry 的 BitLen。若 ESI 有 PdoDivisions 但沒有對應 PDO Entry，Parser 用 Division 數量作為估算並產生 warning。', doubleCheck: '拿 Object Index/SubIndex 去 PDO Entry 表找 BitLen；若找不到，看 Warnings。' }, { table: 'DIO 點位', title: 'Entry Usage', sourceType: 'Parser 判斷', esiPath: '由對應 PDO Entry 帶入', logic: 'DIO 點位表只列有效 Object 產生的點位；Name=NULL 的 reserved entry 不會產生點位。', doubleCheck: '拿本列 Object Index/SubIndex 回 PDO Entry 表查看 Entry Usage。' }, { table: 'DIO 點位', title: 'Local Start Bit', sourceType: 'Parser 衍生', esiPath: '無；不是 ESI 原始欄位', logic: '此 DIO 點位的 Local Start Bit = 對應 PDO Entry 的 Local Start Bit + 此點位的 Bit Offset。代表該點位在所屬 PDO 內的 bit 位置。', doubleCheck: '先在 PDO Entry 表找同一 PDO Index + Object Index/SubIndex 的 Local Start Bit，再加上本列 Bit Offset。' }, { table: 'DIO 點位', title: 'Bit Offset', sourceType: 'Parser 衍生', esiPath: '不是標準 PDO Entry 原始欄位；若有 PdoDivisions，依 Division 出現順序；若無，依 LSB-first 推論', logic: '第 1 個 Division = bit offset 0，第 2 個 = 1。沒有 PdoDivisions 時，Parser 將 BYTE/WORD/DWORD 依 bit0、bit1... 展開。', doubleCheck: 'ESI_VENDOR_SPECIFIC：數 PdoDivisions 裡 Division 順序；INFERRED：檢查 Source 並依 bit0~bitN 推論。' },
];
COLUMN_SOURCES.fieldSourceTable = { 'Table': 'Parser 內建 Data Dictionary：所屬表格名稱', 'Title': 'Parser 內建 Data Dictionary：欄位名稱', '說明': 'Parser 內建 Data Dictionary：欄位用途說明', 'Source Type': 'Parser 內建 Data Dictionary：欄位來源類型', 'ESI XML Path / Key': 'Parser 內建 Data Dictionary：對應 ESI XML path 或 key', 'Logic': 'Parser 內建 Data Dictionary：解析或推論邏輯', 'How to Double Check': 'Parser 內建 Data Dictionary：人工核對方式' };
